static const char* b2s(bool b) { return b ? "True" : "False"; }

struct Counted {
    static int copies;
    static int moves;
    int v;
    explicit Counted(int x) : v(x) {}
    Counted(const Counted& o) : v(o.v) { ++copies; }
    Counted(Counted&& o) noexcept : v(o.v) { o.v = -1; ++moves; }
};
int Counted::copies = 0;
int Counted::moves = 0;

static Counted make_prvalue() { return Counted(7); }              // 保证消除（C++17 起）

static Counted make_named() { Counted t(8); return t; }           // NRVO（此处也消除）

static Counted make_forced_move() { Counted t(9); return std::move(t); }  // 显式 move 禁止消除

int main() {
    Counted::copies = 0; Counted::moves = 0;
    { Counted x = make_prvalue(); (void)x; }
    std::cout << "prvalue RVO copies=" << Counted::copies << " moves=" << Counted::moves << "\n";

    Counted::copies = 0; Counted::moves = 0;
    { Counted x = make_named(); (void)x; }
    std::cout << "named NRVO copies=" << Counted::copies << " moves=" << Counted::moves << "\n";

    Counted::copies = 0; Counted::moves = 0;
    { Counted x = make_forced_move(); (void)x; }
    std::cout << "forced std::move copies=" << Counted::copies << " moves=" << Counted::moves << "\n";

    std::cout << "elision beats move: " << b2s(true) << "\n";
}
